end

# ---- 構文木の部品（規則のアクションから呼ぶ）----
def lf(surface, silent = false)
  Kanbun::Tree::Leaf.new(surface, silent: silent)
end

# 再読文字の葉。読みは Lexicon::SAIDOKU から引く。
def lf_saidoku(surface)
